-- [JLAS-W0108] Consolidated task-owned Learning seed.

-- Apply after sql/migrations/022_learning_owned_consolidated.sql and the normal shared base seeds.

-- Split for GitHub's 50 MB limit (E5, 2026-10-28): apply this file, then sql/seeds/learning_owned_part2.sql.
-- Re-runnable; task-owned source JSON is data/learning-owned/learning-content.json.

SET NAMES utf8mb4;

-- BEGIN sql/seeds/learning_owned_base_source_flag_backfill.sql SHA256 b3d1d093cc57a6366718229d426a419b9862336d5320023aed56626278886af4
-- [JLAS-W0108] Repair an EXISTING database loaded with an older seed_data_jlas.sql.
-- Fresh databases get these flags directly from the generated canonical seed.
-- This script never deletes/reseeds content, changes publication status, or touches
-- books owned by the textbook digitization team. Back up the target DB first.
-- MySQL 8; select the intended database before sourcing this file. Do not use --force.
SET NAMES utf8mb4;

DELIMITER //
DROP PROCEDURE IF EXISTS jlas_backfill_owned_learning_source_20261010//
CREATE PROCEDURE jlas_backfill_owned_learning_source_20261010()
BEGIN
    DECLARE matched_books INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;
    -- IDs are stable only for the canonical base seed. Verify BOTH ID and title;
    -- fail closed if this DB uses a different import layout.
    SELECT COUNT(*) INTO matched_books
      FROM textbook
     WHERE id IN (1, 2, 3, 4, 5, 6)
       AND ((id = 1 AND title = 'Sekai N5 — Giáo trình tiếng Nhật')
         OR (id = 2 AND title = 'Sekai N4 — Giáo trình tiếng Nhật')
         OR (id = 3 AND title = 'Bảng chữ cái tiếng Nhật')
         OR (id = 4 AND title = 'Tiếng Nhật N3')
         OR (id = 5 AND title = 'Tiếng Nhật N2')
         OR (id = 6 AND title = 'Tiếng Nhật N1'));
    IF matched_books <> 6 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'J-LAS base textbook identities differ; no flags changed';
    END IF;

    UPDATE textbook
       SET is_learning_path_source = 1
     WHERE id IN (1, 2, 3, 4, 5, 6)
       AND ((id = 1 AND title = 'Sekai N5 — Giáo trình tiếng Nhật')
         OR (id = 2 AND title = 'Sekai N4 — Giáo trình tiếng Nhật')
         OR (id = 3 AND title = 'Bảng chữ cái tiếng Nhật')
         OR (id = 4 AND title = 'Tiếng Nhật N3')
         OR (id = 5 AND title = 'Tiếng Nhật N2')
         OR (id = 6 AND title = 'Tiếng Nhật N1'));

    SELECT COUNT(*) INTO matched_books
      FROM textbook
     WHERE id IN (1, 2, 3, 4, 5, 6) AND is_learning_path_source = 1;
    IF matched_books <> 6 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'J-LAS learning source flag verification failed';
    END IF;
    COMMIT;
END//
CALL jlas_backfill_owned_learning_source_20261010()//
DROP PROCEDURE jlas_backfill_owned_learning_source_20261010//
DELIMITER ;

-- Postcondition: exactly six base JLPT/Kana books flagged. Status remains unchanged.
SELECT id, title, status, is_learning_path_source
  FROM textbook WHERE id BETWEEN 1 AND 9 ORDER BY id;
-- END sql/seeds/learning_owned_base_source_flag_backfill.sql

