-- BEGIN sql/seeds/learning_owned_source_drafts.sql SHA256 a90c44bc15952fef75243b6aad4efbe0ff986302d9e7d77688cb90f95a00242c
-- Generated task-owned source holding rows. DRAFT only; no lesson/quiz/assessment writes.
SET NAMES utf8mb4;
CREATE TEMPORARY TABLE IF NOT EXISTS learning_owned_source_guard (ok INT NOT NULL CHECK (ok=1));
